Hypothesis APART : forall a n sp0 scr0, (forall i, 0 <= i < n -> aclient L ar (PEC.owned s en k ++ LBX) FF sp0 scr0 (a + i)) -> 0 < n ->
  (a + n <= F \/ F + ff_bytes 0 <= a) /\ (a + n <= F / 8 + SB \/ F / 8 + SB + ff_bytes 0 / 8 <= a) /\ (a + n <= fl \/ fl + 1 <= a).
